			noise = 0.0,
			passes = 4,
			popups = true,
			size = 2,
			special = false,
			vibrancy = 0.0,
			xray = true,
		},
		dim_special = 0.6,
		rounding = 16,
		shadow = {
			enabled = false,
		},
	},
	dwindle = {
		preserve_split = true,
		smart_split = true,
		special_scale_factor = 1.0,
		use_active_for_splits = false,
	},
	ecosystem = {
		no_donation_nag = true,
	},
	general = {
		border_size = 2,
		col = {
			active_border = "0xfffff9f5",
		},
		gaps_in = 4,
		gaps_out = 8,
	},
	gestures = {
		workspace_swipe_use_r = false,
	},
	input = {
